-- =============================================================================
-- Migration 0035: K.1 Theorie A — Primitiveren en de kettingregel
-- =============================================================================
-- Gegenereerd door scripts/k1a-content.ts — niet met de hand bewerken.
--
-- Theorieblok A van K.1: de omgekeerde kettingregel. Zoek in de integrand een
-- kern g(x) met ervóór een factor die (op een constante na) g’(x) is; dan is
-- g’(x) dx = d(g(x)) en hoef je alleen de buitenkant nog te primitiveren.
--
-- Eigen oefenvragen, geen boekopgaven. Elke primitieve wordt nagerekend door
-- src/content/primitieven.test.ts (content/hoofdstuk-k/k1a.json).
--
-- Alleen toevoegen: geen DELETE, DROP, ALTER of UPDATE. Twee keer draaien
-- voegt niets dubbel toe.
--
--   • 1 hoofdstuk, 3 topics, 6 clusters
--   • 36 vragen met elk 4 stappen (144 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('k', $ksql$K — Voortgezette integraalrekening$ksql$, 4, 12, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'k' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('k1a_kern_herkennen', $ksql$De kern herkennen$ksql$, 4, 'primitiveren'),
  ('k1a_primitiveren_ketting', $ksql$Primitiveren met de omgekeerde kettingregel$ksql$, 5, 'primitiveren'),
  ('k1a_toepassingen', $ksql$Oppervlakte en inhoud met de omgekeerde kettingregel$ksql$, 6, 'toepassingen')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

-- 3. Clusters
INSERT INTO public.topic_clusters_new (topic_id, slug, title, order_index, site)
SELECT t.id, v.slug, v.title, v.order_index, 'integralen'
FROM (VALUES
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Invullen met de d(…)-notatie$ksql$, 1),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor welke a lukt het?$ksql$, 2),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$Een macht van een kern$ksql$, 1),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$Wortels en breuken met een kern$ksql$, 2),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$e-macht, ln en gonio met een kern$ksql$, 3),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Oppervlakte en inhoud$ksql$, 1)
) AS v(topic_slug, slug, title, order_index)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
ON CONFLICT (topic_id, slug) DO NOTHING;

