);

-- 5. Stappen (step_order 0 t/m 3)
INSERT INTO public.question_steps_new (question_id, step_order, step_description)
SELECT vr.id, v.step_order, v.step_description
FROM (VALUES
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $4x^{3}\,\mathrm{d}x = \mathrm{d}(\ldots + 2)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. De notatie $\mathrm{d}(G(x)) = G'(x)\,\mathrm{d}x$ draai je om: op de puntjes staat een functie die je differentieert tot wat er vóór de $\mathrm{d}x$ staat.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $4x^{3}\,\mathrm{d}x = \mathrm{d}(\ldots + 2)$$ksql$, 1, $ksql$Vóór de $\mathrm{d}x$ staat $4x^{3}$: één losse macht, zonder kern.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $4x^{3}\,\mathrm{d}x = \mathrm{d}(\ldots + 2)$$ksql$, 2, $ksql$Primitiveer $4x^{3}$ met de machtsregel: $4 \cdot \tfrac{1}{4}x^{4} = x^{4}$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $4x^{3}\,\mathrm{d}x = \mathrm{d}(\ldots + 2)$$ksql$, 3, $ksql$Op de puntjes staat $x^{4}$: $4x^{3}\,\mathrm{d}x = \mathrm{d}(x^{4} + 2)$. Controle: differentieer wat tussen de haakjes staat en je krijgt terug wat er vóór de $\mathrm{d}x$ staat; een losse constante erbij verandert daar niets aan.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $\cos(3x)\,\mathrm{d}x = \mathrm{d}(\ldots - 1)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. De notatie $\mathrm{d}(G(x)) = G'(x)\,\mathrm{d}x$ draai je om: op de puntjes staat een functie die je differentieert tot wat er vóór de $\mathrm{d}x$ staat.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $\cos(3x)\,\mathrm{d}x = \mathrm{d}(\ldots - 1)$$ksql$, 1, $ksql$Vóór de $\mathrm{d}x$ staat $\cos(3x)$: een cosinus met de lineaire kern $3x$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $\cos(3x)\,\mathrm{d}x = \mathrm{d}(\ldots - 1)$$ksql$, 2, $ksql$De primitieve van $\cos(x)$ is $\sin(x)$; door de kern $3x$ komt er een factor $\tfrac{1}{3}$ bij: $\tfrac{1}{3}\sin(3x)$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $\cos(3x)\,\mathrm{d}x = \mathrm{d}(\ldots - 1)$$ksql$, 3, $ksql$Op de puntjes staat $\tfrac{1}{3}\sin(3x)$: $\cos(3x)\,\mathrm{d}x = \mathrm{d}\left(\tfrac{1}{3}\sin(3x) - 1\right)$. Controle: differentieer wat tussen de haakjes staat en je krijgt terug wat er vóór de $\mathrm{d}x$ staat; een losse constante erbij verandert daar niets aan.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $(6x + 2)\,\mathrm{d}x = \mathrm{d}(\ldots + \pi)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. De notatie $\mathrm{d}(G(x)) = G'(x)\,\mathrm{d}x$ draai je om: op de puntjes staat een functie die je differentieert tot wat er vóór de $\mathrm{d}x$ staat.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $(6x + 2)\,\mathrm{d}x = \mathrm{d}(\ldots + \pi)$$ksql$, 1, $ksql$Vóór de $\mathrm{d}x$ staat $6x + 2$: twee losse termen, dus term voor term primitiveren.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $(6x + 2)\,\mathrm{d}x = \mathrm{d}(\ldots + \pi)$$ksql$, 2, $ksql$$6x$ geeft $3x^{2}$ en $2$ geeft $2x$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $(6x + 2)\,\mathrm{d}x = \mathrm{d}(\ldots + \pi)$$ksql$, 3, $ksql$Op de puntjes staat $3x^{2} + 2x$: $(6x + 2)\,\mathrm{d}x = \mathrm{d}(3x^{2} + 2x + \pi)$. Controle: differentieer wat tussen de haakjes staat en je krijgt terug wat er vóór de $\mathrm{d}x$ staat; een losse constante erbij verandert daar niets aan.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $6x\,\mathrm{e}^{3x^{2}}\,\mathrm{d}x = \mathrm{d}(\ldots)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. De notatie $\mathrm{d}(G(x)) = G'(x)\,\mathrm{d}x$ draai je om: op de puntjes staat een functie die je differentieert tot wat er vóór de $\mathrm{d}x$ staat.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $6x\,\mathrm{e}^{3x^{2}}\,\mathrm{d}x = \mathrm{d}(\ldots)$$ksql$, 1, $ksql$Vóór de $\mathrm{d}x$ staat een e-macht met kern $3x^{2}$, en daarvóór de factor $6x$. De afgeleide van de kern is $6x$: dat past precies.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $6x\,\mathrm{e}^{3x^{2}}\,\mathrm{d}x = \mathrm{d}(\ldots)$$ksql$, 2, $ksql$Dus $6x\,\mathrm{d}x = \mathrm{d}(3x^{2})$ en $\int \mathrm{e}^{g}\,\mathrm{d}g = \mathrm{e}^{g}$, met $g = 3x^{2}$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $6x\,\mathrm{e}^{3x^{2}}\,\mathrm{d}x = \mathrm{d}(\ldots)$$ksql$, 3, $ksql$Op de puntjes staat $\mathrm{e}^{3x^{2}}$: $6x\,\mathrm{e}^{3x^{2}}\,\mathrm{d}x = \mathrm{d}\left(\mathrm{e}^{3x^{2}}\right)$. Controle: differentieer wat tussen de haakjes staat en je krijgt terug wat er vóór de $\mathrm{d}x$ staat; een losse constante erbij verandert daar niets aan.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $\dfrac{2x}{x^{2} + 5}\,\mathrm{d}x = \mathrm{d}(\ldots + 4)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. De notatie $\mathrm{d}(G(x)) = G'(x)\,\mathrm{d}x$ draai je om: op de puntjes staat een functie die je differentieert tot wat er vóór de $\mathrm{d}x$ staat.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $\dfrac{2x}{x^{2} + 5}\,\mathrm{d}x = \mathrm{d}(\ldots + 4)$$ksql$, 1, $ksql$Vóór de $\mathrm{d}x$ staat een breuk met de kern $x^{2} + 5$ in de noemer. De afgeleide van die kern is $2x$ en dat is precies de teller.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $\dfrac{2x}{x^{2} + 5}\,\mathrm{d}x = \mathrm{d}(\ldots + 4)$$ksql$, 2, $ksql$Dus $2x\,\mathrm{d}x = \mathrm{d}(x^{2} + 5)$ en $\int \dfrac{1}{g}\,\mathrm{d}g = \ln|g|$, met $g = x^{2} + 5$. Die kern is altijd positief, dus de strepen mogen weg.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $\dfrac{2x}{x^{2} + 5}\,\mathrm{d}x = \mathrm{d}(\ldots + 4)$$ksql$, 3, $ksql$Op de puntjes staat $\ln(x^{2} + 5)$: $\dfrac{2x}{x^{2} + 5}\,\mathrm{d}x = \mathrm{d}\big(\ln(x^{2} + 5) + 4\big)$. Controle: differentieer wat tussen de haakjes staat en je krijgt terug wat er vóór de $\mathrm{d}x$ staat; een losse constante erbij verandert daar niets aan.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $3x^{2}\sqrt{x^{3} + 1}\,\mathrm{d}x = \mathrm{d}(\ldots)$$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. De notatie $\mathrm{d}(G(x)) = G'(x)\,\mathrm{d}x$ draai je om: op de puntjes staat een functie die je differentieert tot wat er vóór de $\mathrm{d}x$ staat.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $3x^{2}\sqrt{x^{3} + 1}\,\mathrm{d}x = \mathrm{d}(\ldots)$$ksql$, 1, $ksql$Vóór de $\mathrm{d}x$ staat een wortel met kern $x^{3} + 1$, en daarvóór $3x^{2}$. De afgeleide van de kern is $3x^{2}$: dat past.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $3x^{2}\sqrt{x^{3} + 1}\,\mathrm{d}x = \mathrm{d}(\ldots)$$ksql$, 2, $ksql$Dus $3x^{2}\,\mathrm{d}x = \mathrm{d}(x^{3} + 1)$ en $\int g^{\frac{1}{2}}\,\mathrm{d}g = \tfrac{2}{3}g^{1\frac{1}{2}} = \tfrac{2}{3}g\sqrt{g}$, met $g = x^{3} + 1$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_differentiaal', $ksql$Vul in: $3x^{2}\sqrt{x^{3} + 1}\,\mathrm{d}x = \mathrm{d}(\ldots)$$ksql$, 3, $ksql$Op de puntjes staat $\tfrac{2}{3}(x^{3} + 1)\sqrt{x^{3} + 1}$: $3x^{2}\sqrt{x^{3} + 1}\,\mathrm{d}x = \mathrm{d}\left(\tfrac{2}{3}(x^{3} + 1)\sqrt{x^{3} + 1}\right)$. Controle: differentieer wat tussen de haakjes staat en je krijgt terug wat er vóór de $\mathrm{d}x$ staat; een losse constante erbij verandert daar niets aan.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (6x + a)\cos(3x^{2} + x)$. Bepaal die $a$ en primitiveer $f$.$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kern met ervóór (of erboven) een factor met $x$ → omgekeerde kettingregel. Die factor moet een constante maal $g'(x)$ zijn; daar volgt $a$ uit.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (6x + a)\cos(3x^{2} + x)$. Bepaal die $a$ en primitiveer $f$.$ksql$, 1, $ksql$Kies de kern: $g(x) = 3x^{2} + x$, dus $g'(x) = 6x + 1$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (6x + a)\cos(3x^{2} + x)$. Bepaal die $a$ en primitiveer $f$.$ksql$, 2, $ksql$De factor vóór de cosinus is $6x + a$. Die moet gelijk zijn aan een constante maal $6x + 1$; bij de $x$-term staat al dezelfde $6$, dus die constante is $1$ en $a = 1$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (6x + a)\cos(3x^{2} + x)$. Bepaal die $a$ en primitiveer $f$.$ksql$, 3, $ksql$Dan is $(6x + 1)\,\mathrm{d}x = \mathrm{d}(3x^{2} + x)$, dus $\int f(x)\,\mathrm{d}x = \int \cos(g)\,\mathrm{d}g = \sin(g)$. Terugschrijven: $F(x) = \sin(3x^{2} + x) + c$. Controle: differentiëren geeft $\cos(3x^{2} + x) \cdot (6x + 1)$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (4x + a)(x^{2} + 3x)^{4}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kern met ervóór (of erboven) een factor met $x$ → omgekeerde kettingregel. Die factor moet een constante maal $g'(x)$ zijn; daar volgt $a$ uit.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (4x + a)(x^{2} + 3x)^{4}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2} + 3x$, dus $g'(x) = 2x + 3$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (4x + a)(x^{2} + 3x)^{4}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 2, $ksql$De factor vóór de haakjes is $4x + a$. Die moet gelijk zijn aan een constante maal $2x + 3$: uit $4x = 2 \cdot 2x$ volgt de constante $2$, en dan is $a = 2 \cdot 3 = 6$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (4x + a)(x^{2} + 3x)^{4}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 3, $ksql$Dan is $\int f(x)\,\mathrm{d}x = \int 2(2x + 3)(x^{2} + 3x)^{4}\,\mathrm{d}x = \int 2g^{4}\,\mathrm{d}g = \tfrac{2}{5}g^{5}$. Terugschrijven: $F(x) = \tfrac{2}{5}(x^{2} + 3x)^{5} + c$. Controle: differentiëren geeft $2(x^{2} + 3x)^{4}(2x + 3) = (4x + 6)(x^{2} + 3x)^{4}$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{6x^{3} + a}{\sqrt{x^{4} + 2x}}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kern met ervóór (of erboven) een factor met $x$ → omgekeerde kettingregel. Die factor moet een constante maal $g'(x)$ zijn; daar volgt $a$ uit.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{6x^{3} + a}{\sqrt{x^{4} + 2x}}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{4} + 2x$, dus $g'(x) = 4x^{3} + 2$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{6x^{3} + a}{\sqrt{x^{4} + 2x}}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 2, $ksql$De teller is $6x^{3} + a$. Die moet gelijk zijn aan een constante maal $4x^{3} + 2$: uit $6x^{3} = 1\tfrac{1}{2} \cdot 4x^{3}$ volgt de constante $1\tfrac{1}{2}$, en dan is $a = 1\tfrac{1}{2} \cdot 2 = 3$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{6x^{3} + a}{\sqrt{x^{4} + 2x}}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 3, $ksql$Dan is $\int f(x)\,\mathrm{d}x = \int 1\tfrac{1}{2}\,g^{-\frac{1}{2}}\,\mathrm{d}g = 1\tfrac{1}{2} \cdot 2\sqrt{g} = 3\sqrt{g}$. Terugschrijven: $F(x) = 3\sqrt{x^{4} + 2x} + c$. Controle: differentiëren geeft $\dfrac{3(4x^{3} + 2)}{2\sqrt{x^{4} + 2x}} = \dfrac{6x^{3} + 3}{\sqrt{x^{4} + 2x}}$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{ax + 5}{x^{2} + 5x + 1}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kern met ervóór (of erboven) een factor met $x$ → omgekeerde kettingregel. Die factor moet een constante maal $g'(x)$ zijn; daar volgt $a$ uit.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{ax + 5}{x^{2} + 5x + 1}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2} + 5x + 1$, dus $g'(x) = 2x + 5$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{ax + 5}{x^{2} + 5x + 1}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 2, $ksql$De teller is $ax + 5$. Die moet gelijk zijn aan een constante maal $2x + 5$: de losse $5$ staat er al, dus die constante is $1$ en $a = 2$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{ax + 5}{x^{2} + 5x + 1}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 3, $ksql$Dan is $\int f(x)\,\mathrm{d}x = \int \dfrac{1}{g}\,\mathrm{d}g = \ln|g|$. Terugschrijven: $F(x) = \ln|x^{2} + 5x + 1| + c$. De strepen blijven staan, want deze kern kan negatief zijn. Controle: differentiëren geeft $\dfrac{2x + 5}{x^{2} + 5x + 1}$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{3x^{2} + a}{(x^{3} + x)^{2}}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kern met ervóór (of erboven) een factor met $x$ → omgekeerde kettingregel. Die factor moet een constante maal $g'(x)$ zijn; daar volgt $a$ uit.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{3x^{2} + a}{(x^{3} + x)^{2}}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{3} + x$, dus $g'(x) = 3x^{2} + 1$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{3x^{2} + a}{(x^{3} + x)^{2}}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 2, $ksql$De teller is $3x^{2} + a$. Die moet gelijk zijn aan een constante maal $3x^{2} + 1$: uit $3x^{2} = 1 \cdot 3x^{2}$ volgt de constante $1$, en dan is $a = 1$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = \dfrac{3x^{2} + a}{(x^{3} + x)^{2}}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 3, $ksql$Schrijf de breuk als macht: $\int g^{-2}\,\mathrm{d}g = -g^{-1}$. Terugschrijven: $F(x) = -\dfrac{1}{x^{3} + x} + c$. Controle: differentiëren geeft $\dfrac{3x^{2} + 1}{(x^{3} + x)^{2}}$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (ax + 6)\sqrt{x^{2} + 6x + 10}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een kern met ervóór (of erboven) een factor met $x$ → omgekeerde kettingregel. Die factor moet een constante maal $g'(x)$ zijn; daar volgt $a$ uit.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (ax + 6)\sqrt{x^{2} + 6x + 10}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2} + 6x + 10$, dus $g'(x) = 2x + 6$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (ax + 6)\sqrt{x^{2} + 6x + 10}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 2, $ksql$De factor vóór de wortel is $ax + 6$. Die moet gelijk zijn aan een constante maal $2x + 6$: de losse $6$ staat er al, dus die constante is $1$ en $a = 2$.$ksql$),
  ('k1a_kern_herkennen', 'k1a_welke_a', $ksql$Voor precies één waarde van $a$ lukt het primitiveren met de omgekeerde kettingregel: $f(x) = (ax + 6)\sqrt{x^{2} + 6x + 10}$. Bepaal die $a$ en primitiveer $f$.$ksql$, 3, $ksql$Dan is $\int f(x)\,\mathrm{d}x = \int g^{\frac{1}{2}}\,\mathrm{d}g = \tfrac{2}{3}g\sqrt{g}$. Terugschrijven: $F(x) = \tfrac{2}{3}(x^{2} + 6x + 10)\sqrt{x^{2} + 6x + 10} + c$. Controle: differentiëren geeft $\sqrt{x^{2} + 6x + 10} \cdot (2x + 6)$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 2x(x^{2} + 5)^{4}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een macht van een kern, met ervóór een factor met $x$ → omgekeerde kettingregel. Kijk of die factor de afgeleide van de kern is.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 2x(x^{2} + 5)^{4}$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2} + 5$, dus $g'(x) = 2x$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 2x(x^{2} + 5)^{4}$ksql$, 2, $ksql$Vóór de haakjes staat precies $2x = g'(x)$, dus $2x\,\mathrm{d}x = \mathrm{d}(x^{2} + 5)$ en $\int 2x(x^{2} + 5)^{4}\,\mathrm{d}x = \int g^{4}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 2x(x^{2} + 5)^{4}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int g^{4}\,\mathrm{d}g = \tfrac{1}{5}g^{5}$. Schrijf de kern terug: $F(x) = \tfrac{1}{5}(x^{2} + 5)^{5} + c$. Controle: differentiëren geeft $(x^{2} + 5)^{4} \cdot 2x$ — dat is $f(x)$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 3x^{2}(x^{3} + 2)^{5}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een macht van een kern, met ervóór een factor met $x$ → omgekeerde kettingregel. Kijk of die factor de afgeleide van de kern is.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 3x^{2}(x^{3} + 2)^{5}$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{3} + 2$, dus $g'(x) = 3x^{2}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 3x^{2}(x^{3} + 2)^{5}$ksql$, 2, $ksql$Vóór de haakjes staat precies $3x^{2} = g'(x)$, dus $3x^{2}\,\mathrm{d}x = \mathrm{d}(x^{3} + 2)$ en $\int 3x^{2}(x^{3} + 2)^{5}\,\mathrm{d}x = \int g^{5}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 3x^{2}(x^{3} + 2)^{5}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int g^{5}\,\mathrm{d}g = \tfrac{1}{6}g^{6}$. Schrijf de kern terug: $F(x) = \tfrac{1}{6}(x^{3} + 2)^{6} + c$. Controle: differentiëren geeft $(x^{3} + 2)^{5} \cdot 3x^{2}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 8x(x^{2} - 3)^{3}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een macht van een kern, met ervóór een factor met $x$ → omgekeerde kettingregel. Kijk of die factor de afgeleide van de kern is.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 8x(x^{2} - 3)^{3}$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2} - 3$, dus $g'(x) = 2x$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 8x(x^{2} - 3)^{3}$ksql$, 2, $ksql$Vóór de haakjes staat $8x$ en dat is $4 \cdot 2x$, dus $\int 8x(x^{2} - 3)^{3}\,\mathrm{d}x = \int 4 \cdot (x^{2} - 3)^{3} \cdot 2x\,\mathrm{d}x = \int 4g^{3}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = 8x(x^{2} - 3)^{3}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int 4g^{3}\,\mathrm{d}g = g^{4}$. Schrijf de kern terug: $F(x) = (x^{2} - 3)^{4} + c$. Controle: differentiëren geeft $4(x^{2} - 3)^{3} \cdot 2x = 8x(x^{2} - 3)^{3}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = x(2x^{2} + 1)^{4}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een macht van een kern, met ervóór een factor met $x$ → omgekeerde kettingregel. Kijk of die factor de afgeleide van de kern is.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = x(2x^{2} + 1)^{4}$ksql$, 1, $ksql$Kies de kern: $g(x) = 2x^{2} + 1$, dus $g'(x) = 4x$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = x(2x^{2} + 1)^{4}$ksql$, 2, $ksql$Vóór de haakjes staat $x$ en dat is $\tfrac{1}{4} \cdot 4x$, dus $\int x(2x^{2} + 1)^{4}\,\mathrm{d}x = \int \tfrac{1}{4}g^{4}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = x(2x^{2} + 1)^{4}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int \tfrac{1}{4}g^{4}\,\mathrm{d}g = \tfrac{1}{20}g^{5}$. Schrijf de kern terug: $F(x) = \tfrac{1}{20}(2x^{2} + 1)^{5} + c$. Controle: differentiëren geeft $\tfrac{1}{4}(2x^{2} + 1)^{4} \cdot 4x = x(2x^{2} + 1)^{4}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = (x + 1)(x^{2} + 2x - 3)^{5}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een macht van een kern, met ervóór een factor met $x$ → omgekeerde kettingregel. Kijk of die factor de afgeleide van de kern is.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = (x + 1)(x^{2} + 2x - 3)^{5}$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2} + 2x - 3$, dus $g'(x) = 2x + 2$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = (x + 1)(x^{2} + 2x - 3)^{5}$ksql$, 2, $ksql$Vóór de haakjes staat $x + 1$ en dat is $\tfrac{1}{2}(2x + 2) = \tfrac{1}{2}g'(x)$, dus $\int (x + 1)(x^{2} + 2x - 3)^{5}\,\mathrm{d}x = \int \tfrac{1}{2}g^{5}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = (x + 1)(x^{2} + 2x - 3)^{5}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int \tfrac{1}{2}g^{5}\,\mathrm{d}g = \tfrac{1}{12}g^{6}$. Schrijf de kern terug: $F(x) = \tfrac{1}{12}(x^{2} + 2x - 3)^{6} + c$. Controle: differentiëren geeft $\tfrac{1}{2}(x^{2} + 2x - 3)^{5}(2x + 2) = (x + 1)(x^{2} + 2x - 3)^{5}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = \dfrac{4x^{3}}{(x^{4} + 1)^{3}}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een macht van een kern, met ervóór een factor met $x$ → omgekeerde kettingregel. Kijk of die factor de afgeleide van de kern is.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = \dfrac{4x^{3}}{(x^{4} + 1)^{3}}$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{4} + 1$, dus $g'(x) = 4x^{3}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = \dfrac{4x^{3}}{(x^{4} + 1)^{3}}$ksql$, 2, $ksql$De teller is precies $4x^{3} = g'(x)$. Schrijf de breuk als macht: $\int \dfrac{4x^{3}}{(x^{4} + 1)^{3}}\,\mathrm{d}x = \int g^{-3}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_macht_kern', $ksql$f(x) = \dfrac{4x^{3}}{(x^{4} + 1)^{3}}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int g^{-3}\,\mathrm{d}g = -\tfrac{1}{2}g^{-2}$. Schrijf de kern terug: $F(x) = -\dfrac{1}{2(x^{4} + 1)^{2}} + c$. Controle: differentiëren geeft $(x^{4} + 1)^{-3} \cdot 4x^{3}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = 2x\sqrt{x^{2} + 4}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een wortel van een kern, met ervóór een factor met $x$ → omgekeerde kettingregel. Schrijf de wortel als macht $\tfrac{1}{2}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = 2x\sqrt{x^{2} + 4}$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2} + 4$, dus $g'(x) = 2x$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = 2x\sqrt{x^{2} + 4}$ksql$, 2, $ksql$Vóór de wortel staat precies $2x = g'(x)$, dus $2x\,\mathrm{d}x = \mathrm{d}(x^{2} + 4)$ en $\int 2x\sqrt{x^{2} + 4}\,\mathrm{d}x = \int g^{\frac{1}{2}}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = 2x\sqrt{x^{2} + 4}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int g^{\frac{1}{2}}\,\mathrm{d}g = \tfrac{2}{3}g^{1\frac{1}{2}} = \tfrac{2}{3}g\sqrt{g}$. Schrijf de kern terug: $F(x) = \tfrac{2}{3}(x^{2} + 4)\sqrt{x^{2} + 4} + c$. Controle: differentiëren geeft $\sqrt{x^{2} + 4} \cdot 2x$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{2x}{x^{2} + 3}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een kern in de noemer → omgekeerde kettingregel. Is de teller een constante maal de afgeleide van de noemer, dan komt er $\ln$ uit.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{2x}{x^{2} + 3}$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2} + 3$, dus $g'(x) = 2x$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{2x}{x^{2} + 3}$ksql$, 2, $ksql$De teller is precies $2x = g'(x)$, dus $\int \dfrac{2x}{x^{2} + 3}\,\mathrm{d}x = \int \dfrac{1}{g}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{2x}{x^{2} + 3}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int \dfrac{1}{g}\,\mathrm{d}g = \ln|g|$. De kern $x^{2} + 3$ is altijd positief, dus de strepen mogen weg: $F(x) = \ln(x^{2} + 3) + c$. Controle: differentiëren geeft $\dfrac{2x}{x^{2} + 3}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{x}{\sqrt{x^{2} + 9}}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een wortel van een kern in de noemer → omgekeerde kettingregel. Schrijf de wortel als macht $-\tfrac{1}{2}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{x}{\sqrt{x^{2} + 9}}$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2} + 9$, dus $g'(x) = 2x$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{x}{\sqrt{x^{2} + 9}}$ksql$, 2, $ksql$De teller is $x = \tfrac{1}{2} \cdot 2x = \tfrac{1}{2}g'(x)$, dus $\int \dfrac{x}{\sqrt{x^{2} + 9}}\,\mathrm{d}x = \int \tfrac{1}{2}g^{-\frac{1}{2}}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{x}{\sqrt{x^{2} + 9}}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int \tfrac{1}{2}g^{-\frac{1}{2}}\,\mathrm{d}g = \tfrac{1}{2} \cdot 2g^{\frac{1}{2}} = \sqrt{g}$. Schrijf de kern terug: $F(x) = \sqrt{x^{2} + 9} + c$. Controle: differentiëren geeft $\dfrac{2x}{2\sqrt{x^{2} + 9}} = \dfrac{x}{\sqrt{x^{2} + 9}}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{8x}{4x^{2} + 5}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een kern in de noemer → omgekeerde kettingregel. Is de teller een constante maal de afgeleide van de noemer, dan komt er $\ln$ uit.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{8x}{4x^{2} + 5}$ksql$, 1, $ksql$Kies de kern: $g(x) = 4x^{2} + 5$, dus $g'(x) = 8x$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{8x}{4x^{2} + 5}$ksql$, 2, $ksql$De teller is precies $8x = g'(x)$, dus $\int \dfrac{8x}{4x^{2} + 5}\,\mathrm{d}x = \int \dfrac{1}{g}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{8x}{4x^{2} + 5}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int \dfrac{1}{g}\,\mathrm{d}g = \ln|g|$. Deze kern is altijd positief: $F(x) = \ln(4x^{2} + 5) + c$. Controle: differentiëren geeft $\dfrac{8x}{4x^{2} + 5}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = x\sqrt{7 - x^{2}}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een wortel van een kern, met ervóór een factor met $x$ → omgekeerde kettingregel. Schrijf de wortel als macht $\tfrac{1}{2}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = x\sqrt{7 - x^{2}}$ksql$, 1, $ksql$Kies de kern: $g(x) = 7 - x^{2}$, dus $g'(x) = -2x$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = x\sqrt{7 - x^{2}}$ksql$, 2, $ksql$Let op het minteken: $x = -\tfrac{1}{2} \cdot (-2x) = -\tfrac{1}{2}g'(x)$, dus $\int x\sqrt{7 - x^{2}}\,\mathrm{d}x = \int -\tfrac{1}{2}g^{\frac{1}{2}}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = x\sqrt{7 - x^{2}}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int -\tfrac{1}{2}g^{\frac{1}{2}}\,\mathrm{d}g = -\tfrac{1}{2} \cdot \tfrac{2}{3}g\sqrt{g} = -\tfrac{1}{3}g\sqrt{g}$. Schrijf de kern terug: $F(x) = -\tfrac{1}{3}(7 - x^{2})\sqrt{7 - x^{2}} + c$. Controle: differentiëren geeft $-\tfrac{1}{2}\sqrt{7 - x^{2}} \cdot (-2x) = x\sqrt{7 - x^{2}}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{6x^{2}}{\sqrt{x^{3} + 5}}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een breuk met een wortel van een kern in de noemer → omgekeerde kettingregel. Schrijf de wortel als macht $-\tfrac{1}{2}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{6x^{2}}{\sqrt{x^{3} + 5}}$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{3} + 5$, dus $g'(x) = 3x^{2}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{6x^{2}}{\sqrt{x^{3} + 5}}$ksql$, 2, $ksql$De teller is $6x^{2} = 2 \cdot 3x^{2} = 2g'(x)$, dus $\int \dfrac{6x^{2}}{\sqrt{x^{3} + 5}}\,\mathrm{d}x = \int 2g^{-\frac{1}{2}}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_wortel_breuk', $ksql$f(x) = \dfrac{6x^{2}}{\sqrt{x^{3} + 5}}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int 2g^{-\frac{1}{2}}\,\mathrm{d}g = 2 \cdot 2\sqrt{g} = 4\sqrt{g}$. Schrijf de kern terug: $F(x) = 4\sqrt{x^{3} + 5} + c$. Controle: differentiëren geeft $\dfrac{4 \cdot 3x^{2}}{2\sqrt{x^{3} + 5}} = \dfrac{6x^{2}}{\sqrt{x^{3} + 5}}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = 2x\,\mathrm{e}^{x^{2}}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een e-macht met een kern in de exponent, met ervóór een factor met $x$ → omgekeerde kettingregel.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = 2x\,\mathrm{e}^{x^{2}}$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2}$, dus $g'(x) = 2x$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = 2x\,\mathrm{e}^{x^{2}}$ksql$, 2, $ksql$Vóór de e-macht staat precies $2x = g'(x)$, dus $2x\,\mathrm{d}x = \mathrm{d}(x^{2})$ en $\int 2x\,\mathrm{e}^{x^{2}}\,\mathrm{d}x = \int \mathrm{e}^{g}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = 2x\,\mathrm{e}^{x^{2}}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int \mathrm{e}^{g}\,\mathrm{d}g = \mathrm{e}^{g}$. Schrijf de kern terug: $F(x) = \mathrm{e}^{x^{2}} + c$. Controle: differentiëren geeft $\mathrm{e}^{x^{2}} \cdot 2x$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = 3x^{2}\cos(x^{3})$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een sinus of cosinus van een kern, met ervóór een factor met $x$ → omgekeerde kettingregel.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = 3x^{2}\cos(x^{3})$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{3}$, dus $g'(x) = 3x^{2}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = 3x^{2}\cos(x^{3})$ksql$, 2, $ksql$Vóór de cosinus staat precies $3x^{2} = g'(x)$, dus $3x^{2}\,\mathrm{d}x = \mathrm{d}(x^{3})$ en $\int 3x^{2}\cos(x^{3})\,\mathrm{d}x = \int \cos(g)\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = 3x^{2}\cos(x^{3})$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int \cos(g)\,\mathrm{d}g = \sin(g)$. Schrijf de kern terug: $F(x) = \sin(x^{3}) + c$. Controle: differentiëren geeft $\cos(x^{3}) \cdot 3x^{2}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = x\,\mathrm{e}^{-2x^{2}}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een e-macht met een kern in de exponent, met ervóór een factor met $x$ → omgekeerde kettingregel.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = x\,\mathrm{e}^{-2x^{2}}$ksql$, 1, $ksql$Kies de kern: $g(x) = -2x^{2}$, dus $g'(x) = -4x$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = x\,\mathrm{e}^{-2x^{2}}$ksql$, 2, $ksql$Vóór de e-macht staat $x$ en dat is $-\tfrac{1}{4} \cdot (-4x) = -\tfrac{1}{4}g'(x)$, dus $\int x\,\mathrm{e}^{-2x^{2}}\,\mathrm{d}x = \int -\tfrac{1}{4}\mathrm{e}^{g}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = x\,\mathrm{e}^{-2x^{2}}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int -\tfrac{1}{4}\mathrm{e}^{g}\,\mathrm{d}g = -\tfrac{1}{4}\mathrm{e}^{g}$. Schrijf de kern terug: $F(x) = -\tfrac{1}{4}\mathrm{e}^{-2x^{2}} + c$. Controle: differentiëren geeft $-\tfrac{1}{4}\mathrm{e}^{-2x^{2}} \cdot (-4x) = x\,\mathrm{e}^{-2x^{2}}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \dfrac{4\ln(x)}{x}$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een $\ln$ met ervóór $\dfrac{1}{x}$ → omgekeerde kettingregel. De afgeleide van $\ln(x)$ is juist $\dfrac{1}{x}$, dus neem $\ln(x)$ als kern.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \dfrac{4\ln(x)}{x}$ksql$, 1, $ksql$Kies de kern: $g(x) = \ln(x)$, dus $g'(x) = \dfrac{1}{x}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \dfrac{4\ln(x)}{x}$ksql$, 2, $ksql$Schrijf $f(x) = 4\ln(x) \cdot \dfrac{1}{x}$. Omdat $\dfrac{1}{x}\,\mathrm{d}x = \mathrm{d}\ln(x)$ wordt dit $\int 4g\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \dfrac{4\ln(x)}{x}$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int 4g\,\mathrm{d}g = 2g^{2}$. Schrijf de kern terug: $F(x) = 2\ln^{2}(x) + c$. Controle: differentiëren geeft $4\ln(x) \cdot \dfrac{1}{x}$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \sin(x)\cos^{3}(x)$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een macht van $\cos(x)$, met ervóór $\sin(x)$ → omgekeerde kettingregel. De afgeleide van $\cos(x)$ is $-\sin(x)$, dus neem $\cos(x)$ als kern.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \sin(x)\cos^{3}(x)$ksql$, 1, $ksql$Kies de kern: $g(x) = \cos(x)$, dus $g'(x) = -\sin(x)$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \sin(x)\cos^{3}(x)$ksql$, 2, $ksql$Let op het minteken: $\sin(x) = -1 \cdot (-\sin(x)) = -g'(x)$, dus $\int \sin(x)\cos^{3}(x)\,\mathrm{d}x = \int -g^{3}\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = \sin(x)\cos^{3}(x)$ksql$, 3, $ksql$Primitiveer de buitenkant: $\int -g^{3}\,\mathrm{d}g = -\tfrac{1}{4}g^{4}$. Schrijf de kern terug: $F(x) = -\tfrac{1}{4}\cos^{4}(x) + c$. Controle: differentiëren geeft $-\cos^{3}(x) \cdot (-\sin(x)) = \sin(x)\cos^{3}(x)$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = 3x\ln(x^{2} + 4)$ksql$, 0, $ksql$Alleen deel 2 van de driedeling speelt hier: bereken de goede integraal. Buitenste schil: een $\ln$ van een kern, met ervóór een factor met $x$ → omgekeerde kettingregel. De buitenkant $\ln$ primitiveer je met $\int \ln(g)\,\mathrm{d}g = g\ln(g) - g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = 3x\ln(x^{2} + 4)$ksql$, 1, $ksql$Kies de kern: $g(x) = x^{2} + 4$, dus $g'(x) = 2x$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = 3x\ln(x^{2} + 4)$ksql$, 2, $ksql$Vóór de $\ln$ staat $3x$ en dat is $1\tfrac{1}{2} \cdot 2x = 1\tfrac{1}{2}g'(x)$, dus $\int 3x\ln(x^{2} + 4)\,\mathrm{d}x = \int 1\tfrac{1}{2}\ln(g)\,\mathrm{d}g$.$ksql$),
  ('k1a_primitiveren_ketting', 'k1a_e_ln_gonio', $ksql$f(x) = 3x\ln(x^{2} + 4)$ksql$, 3, $ksql$Primitiveer de buitenkant met de standaardprimitieve van $\ln$: $\int 1\tfrac{1}{2}\ln(g)\,\mathrm{d}g = 1\tfrac{1}{2}\big(g\ln(g) - g\big)$. Schrijf de kern terug: $F(x) = \tfrac{3}{2}\big((x^{2} + 4)\ln(x^{2} + 4) - (x^{2} + 4)\big) + c$. Controle: differentiëren geeft $\tfrac{3}{2}\left(2x\ln(x^{2} + 4) + (x^{2} + 4)\cdot\dfrac{2x}{x^{2} + 4} - 2x\right) = 3x\ln(x^{2} + 4)$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x(x^{2} + 1)^{3}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: vertaal het verhaaltje naar een integraal. De grafiek snijdt de $x$-as bij $x = 0$ en is positief tussen $0$ en $1$, dus de oppervlakte is $\int_{0}^{1} f(x)\,\mathrm{d}x$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x(x^{2} + 1)^{3}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$De integraal: $\int_{0}^{1} 2x(x^{2} + 1)^{3}\,\mathrm{d}x$. Deel 2: welke standaardvorm is dit? Een macht van de kern $g(x) = x^{2} + 1$, met ervóór $g'(x) = 2x$ → omgekeerde kettingregel.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x(x^{2} + 1)^{3}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Primitiveer: $\int g^{3}\,\mathrm{d}g = \tfrac{1}{4}g^{4}$, dus $F(x) = \tfrac{1}{4}(x^{2} + 1)^{4}$. De integratieconstante laat je weg; die valt bij het aftrekken toch weg.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x(x^{2} + 1)^{3}$, de $x$-as en de lijn $x = 1$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $\big[\tfrac{1}{4}(x^{2} + 1)^{4}\big]_{0}^{1} = \tfrac{1}{4} \cdot 2^{4} - \tfrac{1}{4} \cdot 1 = 4 - \tfrac{1}{4} = \tfrac{15}{4}$. De oppervlakte is $3\tfrac{3}{4}$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x}{x^{2} + 1}$, de $x$-as en de lijn $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: vertaal het verhaaltje naar een integraal. De grafiek snijdt de $x$-as bij $x = 0$ en is positief tussen $0$ en $2$, dus de oppervlakte is $\int_{0}^{2} f(x)\,\mathrm{d}x$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x}{x^{2} + 1}$, de $x$-as en de lijn $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$De integraal: $\int_{0}^{2} \dfrac{2x}{x^{2} + 1}\,\mathrm{d}x$. Deel 2: een breuk met de kern $g(x) = x^{2} + 1$ in de noemer, en de teller is precies $g'(x) = 2x$ → omgekeerde kettingregel, met $\ln$ als uitkomst.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x}{x^{2} + 1}$, de $x$-as en de lijn $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Primitiveer: $\int \dfrac{1}{g}\,\mathrm{d}g = \ln|g|$, dus $F(x) = \ln(x^{2} + 1)$; die kern is altijd positief.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x}{x^{2} + 1}$, de $x$-as en de lijn $x = 2$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $\big[\ln(x^{2} + 1)\big]_{0}^{2} = \ln(5) - \ln(1) = \ln(5)$. Exact laten staan, dus niet afronden.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\sqrt{x^{2} + 9}$, de $x$-as en de lijnen $x = 0$ en $x = 4$. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Deel 1 van de driedeling: vertaal het verhaaltje naar een integraal. Op $[0, 4]$ ligt de grafiek boven de $x$-as, dus de oppervlakte is $\int_{0}^{4} f(x)\,\mathrm{d}x$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\sqrt{x^{2} + 9}$, de $x$-as en de lijnen $x = 0$ en $x = 4$. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$De integraal: $\int_{0}^{4} x\sqrt{x^{2} + 9}\,\mathrm{d}x$. Deel 2: een wortel met kern $g(x) = x^{2} + 9$; er staat $x = \tfrac{1}{2}g'(x)$ vóór → omgekeerde kettingregel.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\sqrt{x^{2} + 9}$, de $x$-as en de lijnen $x = 0$ en $x = 4$. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Primitiveer: $\int \tfrac{1}{2}g^{\frac{1}{2}}\,\mathrm{d}g = \tfrac{1}{3}g\sqrt{g}$, dus $F(x) = \tfrac{1}{3}(x^{2} + 9)\sqrt{x^{2} + 9}$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = x\sqrt{x^{2} + 9}$, de $x$-as en de lijnen $x = 0$ en $x = 4$. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$Vul de grenzen in: $\tfrac{1}{3} \cdot 25 \cdot 5 - \tfrac{1}{3} \cdot 9 \cdot 3 = \tfrac{125}{3} - 9 = \tfrac{98}{3}$. De oppervlakte is $32\tfrac{2}{3}$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$De grafiek van $f(x) = \dfrac{2x}{x^{2} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(10)$. Bereken exact $p$.$ksql$, 0, $ksql$Deel 1 van de driedeling: de oppervlakte is $\int_{0}^{p} \dfrac{2x}{x^{2} + 1}\,\mathrm{d}x$, en die moet $\ln(10)$ worden.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$De grafiek van $f(x) = \dfrac{2x}{x^{2} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(10)$. Bereken exact $p$.$ksql$, 1, $ksql$Deel 2: een breuk met kern $g(x) = x^{2} + 1$ in de noemer en teller $g'(x) = 2x$ → omgekeerde kettingregel, met $\ln$ als uitkomst.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$De grafiek van $f(x) = \dfrac{2x}{x^{2} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(10)$. Bereken exact $p$.$ksql$, 2, $ksql$Primitiveer en vul de grenzen in: $\big[\ln(x^{2} + 1)\big]_{0}^{p} = \ln(p^{2} + 1) - \ln(1) = \ln(p^{2} + 1)$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$De grafiek van $f(x) = \dfrac{2x}{x^{2} + 1}$, de $x$-as en de lijnen $x = 0$ en $x = p$ met $p > 0$ sluiten een vlakdeel in met oppervlakte $\ln(10)$. Bereken exact $p$.$ksql$, 3, $ksql$Deel 3: los de vergelijking op. Uit $\ln(p^{2} + 1) = \ln(10)$ volgt $p^{2} + 1 = 10$, dus $p^{2} = 9$ en $p = 3$ (want $p > 0$).$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x}\,\mathrm{e}^{x^{2}}$, de $x$-as en de lijn $x = 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Deel 1 van de driedeling: wentelen om de $x$-as geeft inhoud $\pi\int_{a}^{b} \big(f(x)\big)^{2}\,\mathrm{d}x$. Hier loopt $x$ van $0$ (daar begint de grafiek) tot $1$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x}\,\mathrm{e}^{x^{2}}$, de $x$-as en de lijn $x = 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$Kwadrateer eerst: $\big(f(x)\big)^{2} = \left(\sqrt{x}\,\mathrm{e}^{x^{2}}\right)^{2} = x\,\mathrm{e}^{2x^{2}}$. De integraal wordt $\pi\int_{0}^{1} x\,\mathrm{e}^{2x^{2}}\,\mathrm{d}x$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x}\,\mathrm{e}^{x^{2}}$, de $x$-as en de lijn $x = 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Deel 2: een e-macht met kern $g(x) = 2x^{2}$, dus $g'(x) = 4x$ en $x = \tfrac{1}{4}g'(x)$. Primitiveren geeft $\int \tfrac{1}{4}\mathrm{e}^{g}\,\mathrm{d}g = \tfrac{1}{4}\mathrm{e}^{2x^{2}}$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x}\,\mathrm{e}^{x^{2}}$, de $x$-as en de lijn $x = 1$. Het lichaam $L$ ontstaat als $V$ wentelt om de $x$-as. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$Vul de grenzen in: $\pi\big[\tfrac{1}{4}\mathrm{e}^{2x^{2}}\big]_{0}^{1} = \pi\left(\tfrac{1}{4}\mathrm{e}^{2} - \tfrac{1}{4}\right) = \tfrac{1}{4}\pi\left(\mathrm{e}^{2} - 1\right)$. Exact laten staan.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \tfrac{1}{2}\sqrt{x}\,\mathrm{e}^{x^{2}}$, de $x$-as en de lijn $x = p$ met $p > 0$. Het lichaam $L_p$ ontstaat als $V_p$ wentelt om de $x$-as. Bereken exact voor welke $p$ de inhoud van $L_p$ gelijk is aan $3\pi$. Schrijf het antwoord in de vorm $p = \sqrt{\ln(a)}$.$ksql$, 0, $ksql$Deel 1 van de driedeling: de inhoud is $\pi\int_{0}^{p} \big(f(x)\big)^{2}\,\mathrm{d}x$, en die moet $3\pi$ worden.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \tfrac{1}{2}\sqrt{x}\,\mathrm{e}^{x^{2}}$, de $x$-as en de lijn $x = p$ met $p > 0$. Het lichaam $L_p$ ontstaat als $V_p$ wentelt om de $x$-as. Bereken exact voor welke $p$ de inhoud van $L_p$ gelijk is aan $3\pi$. Schrijf het antwoord in de vorm $p = \sqrt{\ln(a)}$.$ksql$, 1, $ksql$Kwadrateer eerst: $\big(f(x)\big)^{2} = \tfrac{1}{4}x\,\mathrm{e}^{2x^{2}}$. De inhoud is dus $\pi\int_{0}^{p} \tfrac{1}{4}x\,\mathrm{e}^{2x^{2}}\,\mathrm{d}x$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \tfrac{1}{2}\sqrt{x}\,\mathrm{e}^{x^{2}}$, de $x$-as en de lijn $x = p$ met $p > 0$. Het lichaam $L_p$ ontstaat als $V_p$ wentelt om de $x$-as. Bereken exact voor welke $p$ de inhoud van $L_p$ gelijk is aan $3\pi$. Schrijf het antwoord in de vorm $p = \sqrt{\ln(a)}$.$ksql$, 2, $ksql$Deel 2: kern $g(x) = 2x^{2}$ met $g'(x) = 4x$, dus $\tfrac{1}{4}x = \tfrac{1}{16}g'(x)$. Primitiveren en invullen geeft $\pi\big[\tfrac{1}{16}\mathrm{e}^{2x^{2}}\big]_{0}^{p} = \tfrac{1}{16}\pi\left(\mathrm{e}^{2p^{2}} - 1\right)$.$ksql$),
  ('k1a_toepassingen', 'k1a_opp_inhoud', $ksql$Het vlakdeel $V_p$ wordt ingesloten door de grafiek van $f(x) = \tfrac{1}{2}\sqrt{x}\,\mathrm{e}^{x^{2}}$, de $x$-as en de lijn $x = p$ met $p > 0$. Het lichaam $L_p$ ontstaat als $V_p$ wentelt om de $x$-as. Bereken exact voor welke $p$ de inhoud van $L_p$ gelijk is aan $3\pi$. Schrijf het antwoord in de vorm $p = \sqrt{\ln(a)}$.$ksql$, 3, $ksql$Deel 3: los de vergelijking op. Uit $\tfrac{1}{16}\pi\left(\mathrm{e}^{2p^{2}} - 1\right) = 3\pi$ volgt $\mathrm{e}^{2p^{2}} = 49$, dus $2p^{2} = \ln(49) = 2\ln(7)$ en $p^{2} = \ln(7)$. Omdat $p > 0$: $p = \sqrt{\ln(7)}$.$ksql$)
) AS v(topic_slug, cluster_slug, latex_body, step_order, step_description)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
JOIN public.questions_new vr ON vr.latex_body = v.latex_body AND vr.cluster_id = cl.id
ON CONFLICT (question_id, step_order) DO NOTHING;

-- 6. Controle
DO $do$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k1a_differentiaal' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k1a_kern_herkennen' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k1a_differentiaal hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k1a_welke_a' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k1a_kern_herkennen' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k1a_welke_a hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k1a_macht_kern' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k1a_primitiveren_ketting' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k1a_macht_kern hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k1a_wortel_breuk' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k1a_primitiveren_ketting' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k1a_wortel_breuk hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k1a_e_ln_gonio' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k1a_primitiveren_ketting' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k1a_e_ln_gonio hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k1a_opp_inhoud' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k1a_toepassingen' AND site = 'integralen'));
  IF n <> 6 THEN RAISE EXCEPTION 'Cluster k1a_opp_inhoud hoort 6 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.question_steps_new s
  JOIN public.questions_new vr ON vr.id = s.question_id
  JOIN public.topics_new t ON t.id = vr.topic_id
  WHERE t.site = 'integralen' AND t.slug IN ('k1a_kern_herkennen', 'k1a_primitiveren_ketting', 'k1a_toepassingen');
  IF n <> 144 THEN RAISE EXCEPTION 'Deze topics horen samen 144 stappen te hebben, gevonden %', n; END IF;
END $do$;

COMMIT;
